export function calcTotal(items: Item[]): number {
  return items.reduce((s, i) => s + i.price * i.qty, 0);
}

export function summary(items: Item[]) {
  const t = calcTotal(items);
  return { total: t, label: `Total: ${calcTotal(items)}` };
}

export function isFree(items: Item[]) {
  return calcTotal(items) === 0;
}

